 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T_X, typename T_G>
class KernelHardsigmoidBackward {
public:
    __aicore__ inline KernelHardsigmoidBackward() {}

    __aicore__ inline void Init(GM_ADDR g, GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            gGm.SetGlobalBuffer((__gm__ T_G *)g + offset, formerLength);
            xGm.SetGlobalBuffer((__gm__ T_X *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T_X *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            gGm.SetGlobalBuffer((__gm__ T_G *)g + offset, tailLength);
            xGm.SetGlobalBuffer((__gm__ T_X *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T_X *)y + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueG, BUFFER_NUM, tileLength * sizeof(T_G));
        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T_X));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T_X));

        if constexpr (sizeof(T_G) < sizeof(float)) {
            pipe.InitBuffer(castBufG, tileLength * sizeof(float));
        }
        if constexpr (sizeof(T_X) < sizeof(float)) {
            pipe.InitBuffer(castBufX, tileLength * sizeof(float));
        }

        pipe.InitBuffer(h1Buf, tileLength * sizeof(float));
        pipe.InitBuffer(negBuf, tileLength * sizeof(float));
        pipe.InitBuffer(h2Buf, tileLength * sizeof(float));
        pipe.InitBuffer(hBuf, tileLength * sizeof(float));
        pipe.InitBuffer(zeroBuf, tileLength * sizeof(float));
        pipe.InitBuffer(maskBuf, tileLength * sizeof(float));
        pipe.InitBuffer(gradBuf, tileLength * sizeof(float));

        if constexpr (sizeof(T_X) < sizeof(float)) {
            pipe.InitBuffer(yFp32Buf, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignElements = 32 / static_cast<int64_t>(sizeof(T_X));
        int64_t alignedTailLen = ((tailTileLength + alignElements - 1) / alignElements) * alignElements;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, tailTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T_G> gLocal = inQueueG.AllocTensor<T_G>();
        AscendC::DataCopyExtParams copyParamsG{1, static_cast<uint32_t>(curTileLength * sizeof(T_G)), 0, 0, 0};
        AscendC::DataCopyPad(gLocal, gGm[progress * this->tileLength], copyParamsG);
        inQueueG.EnQue(gLocal);

        AscendC::LocalTensor<T_X> xLocal = inQueueX.AllocTensor<T_X>();
        AscendC::DataCopyExtParams copyParamsX{1, static_cast<uint32_t>(curTileLength * sizeof(T_X)), 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParamsX);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T_G> gLocal = inQueueG.DeQue<T_G>();
        AscendC::LocalTensor<T_X> xLocal = inQueueX.DeQue<T_X>();

        if constexpr (sizeof(T_X) == sizeof(float) && sizeof(T_G) == sizeof(float)) {
            // Both inputs are FP32: direct compute
            AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
            ComputeFp32Core(yLocal, xLocal, gLocal, curTileLength);
            outQueueY.EnQue<float>(yLocal);
        } else {
            // At least one input is non-FP32: Cast inputs → FP32 compute → Cast output
            AscendC::LocalTensor<float> gFp32;
            if constexpr (sizeof(T_G) < sizeof(float)) {
                gFp32 = castBufG.Get<float>();
                AscendC::Cast(gFp32, gLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            } else {
                gFp32 = gLocal;
            }

            AscendC::LocalTensor<float> xFp32;
            if constexpr (sizeof(T_X) < sizeof(float)) {
                xFp32 = castBufX.Get<float>();
                AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            } else {
                xFp32 = xLocal;
            }

            AscendC::LocalTensor<float> yFp32;
            if constexpr (sizeof(T_X) < sizeof(float)) {
                yFp32 = yFp32Buf.Get<float>();
            } else {
                yFp32 = outQueueY.AllocTensor<float>();
            }
            ComputeFp32Core(yFp32, xFp32, gFp32, curTileLength);

            if constexpr (sizeof(T_X) < sizeof(float)) {
                AscendC::LocalTensor<T_X> yLocal = outQueueY.AllocTensor<T_X>();
                AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
                outQueueY.EnQue<T_X>(yLocal);
            } else {
                outQueueY.EnQue<float>(yFp32);
            }
        }

        inQueueG.FreeTensor(gLocal);
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void ComputeFp32Core(
        AscendC::LocalTensor<float> yLocal,
        AscendC::LocalTensor<float> xFp32,
        AscendC::LocalTensor<float> gFp32,
        int64_t len)
    {
        AscendC::LocalTensor<float> h1Local = h1Buf.Get<float>();
        AscendC::LocalTensor<float> negLocal = negBuf.Get<float>();
        AscendC::LocalTensor<float> h2Local = h2Buf.Get<float>();
        AscendC::LocalTensor<float> hLocal = hBuf.Get<float>();
        AscendC::LocalTensor<float> zeroLocal = zeroBuf.Get<float>();
        AscendC::LocalTensor<uint8_t> maskLocal = maskBuf.Get<uint8_t>();
        AscendC::LocalTensor<float> gradLocal = gradBuf.Get<float>();

        // h1 = Relu(x + 3)
        AscendC::Adds(h1Local, xFp32, 3.0f, len);
        AscendC::Relu(h1Local, h1Local, len);

        // h2 = Relu(3 - x)
        AscendC::Muls(negLocal, xFp32, -1.0f, len);
        AscendC::Adds(h2Local, negLocal, 3.0f, len);
        AscendC::Relu(h2Local, h2Local, len);

        // h = Min(h1, h2), h > 0 when -3 < x < 3, h == 0 otherwise
        AscendC::Min(hLocal, h1Local, h2Local, len);

        // Fill zero buffer
        AscendC::Duplicate(zeroLocal, 0.0f, len);

        // mask = (h > 0)
        AscendC::Compare(maskLocal, hLocal, zeroLocal, AscendC::CMPMODE::GT, len);

        // grad_scaled = g / 6.0
        float oneOverSix = 1.0f / 6.0f;
        AscendC::Muls(gradLocal, gFp32, oneOverSix, len);

        // result = (h > 0) ? grad_scaled : 0
        AscendC::Select(yLocal, maskLocal, gradLocal, zeroLocal,
                        AscendC::SELMODE::VSEL_CMPMASK_SPR, len);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T_X> yLocal = outQueueY.DeQue<T_X>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T_X)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueG;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;

    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufG;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> h1Buf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> negBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> h2Buf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> hBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> zeroBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maskBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gradBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yFp32Buf;

    AscendC::GlobalTensor<T_X> xGm;
    AscendC::GlobalTensor<T_G> gGm;
    AscendC::GlobalTensor<T_X> yGm;

    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void hardsigmoid_backward(
    GM_ADDR g, GM_ADDR x, GM_ADDR y,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength,
    int64_t dtypeSizeX, int64_t dtypeSizeG)
{
    if (dtypeSizeX == 4 && dtypeSizeG == 4) {
        KernelHardsigmoidBackward<float, float> op;
        op.Init(g, x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeSizeX == 2 && dtypeSizeG == 4) {
        KernelHardsigmoidBackward<half, float> op;
        op.Init(g, x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeSizeX == 4 && dtypeSizeG == 2) {
        KernelHardsigmoidBackward<float, half> op;
        op.Init(g, x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelHardsigmoidBackward<half, half> op;
        op.Init(g, x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
