#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_hardsigmoid_backward.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t SYSTEM_WORKSPACE_SIZE = 16 * 1024 * 1024;  // 16MB

at::Tensor hardsigmoid_backward(const at::Tensor &grad_output, const at::Tensor &self_x)
{
    // Input validation
    TORCH_CHECK(grad_output.scalar_type() == at::kHalf ||
                grad_output.scalar_type() == at::kFloat ||
                grad_output.scalar_type() == at::kBFloat16,
                "hardsigmoid_backward: grad_output only supports float16, float32, bfloat16, got ",
                grad_output.scalar_type());
    TORCH_CHECK(self_x.scalar_type() == at::kHalf ||
                self_x.scalar_type() == at::kFloat ||
                self_x.scalar_type() == at::kBFloat16,
                "hardsigmoid_backward: self_x only supports float16, float32, bfloat16, got ",
                self_x.scalar_type());

    int64_t totalLength = grad_output.numel();
    if (totalLength == 0) {
        return at::empty_like(self_x);
    }

    // Output has same dtype as self_x
    at::Tensor output = at::empty_like(self_x);

    int64_t dtypeSizeX = self_x.element_size();
    int64_t dtypeSizeG = grad_output.element_size();

    // Get hardware parameters
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // Block-level tiling (core-level split, Cache Line aligned)
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // UB-level tiling (within-core split)
    // bufferCoefficient = 52 for all dtype combinations
    // (3 TQue*BUFFER_NUM*sizeof + 8 TBuf*sizeof(float) + conditional cast/yFp32 bufs)
    int64_t bufferCoefficient = 52;
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;

    // 32B alignment: use max dtype size for alignment calculation
    int64_t maxDtypeSize = dtypeSizeX > dtypeSizeG ? dtypeSizeX : dtypeSizeG;
    if (maxDtypeSize == 0) { maxDtypeSize = 1; }
    int64_t alignElements = 32 / maxDtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(hardsigmoid_backward, blockDim,
                    grad_output, self_x, output,
                    formerNum, formerLength, tailLength, tileLength,
                    dtypeSizeX, dtypeSizeG);

    return output;
}

}  // namespace ascend_kernel
