12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelRelu {
17	public:
18	    __aicore__ inline KernelRelu() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	        int64_t tailIdx;
26	
27	        if (blockIdx < formerNum) {
28	            this->blockLength = formerLength;
29	            int64_t offset = formerLength * blockIdx;
30	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
31	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
32	        } else {
33	            this->blockLength = tailLength;
34	            tailIdx = blockIdx - formerNum;
35	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
36	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
37	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
38	        }
39	
40	        this->tileLength = tileLength;
41	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
42	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
43	
44	        // FP32 临时缓冲区，仅 fp16/bf16 升精度路径使用
45	        if constexpr (sizeof(T) != sizeof(float)) {
46	            pipe.InitBuffer(castBufX, tileLength * sizeof(float));
47	            pipe.InitBuffer(castBufY, tileLength * sizeof(float));
48	        }
49	    }
50	
51	    __aicore__ inline void Process()
52	    {
53	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
54	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
55	
56	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
57	        if (alignNum == 0) { alignNum = 1; }
58	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
59	
60	        for (int64_t i = 0; i < tileNum - 1; ++i) {
61	            CopyIn(i, this->tileLength);
62	            Compute(i, this->tileLength);
63	            CopyOut(i, this->tileLength);
64	        }
65	        if (tileNum > 0) {
66	            CopyIn(tileNum - 1, alignedTailLen);
67	            Compute(tileNum - 1, alignedTailLen);
68	            CopyOut(tileNum - 1, alignedTailLen);
69	        }
70	    }
71	
72	private:
73	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
74	    {
75	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
76	        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], curTileLength);
77	        inQueueX.EnQue(xLocal);
78	    }
79	
80	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
81	    {
82	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
83	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
84	
85	        if constexpr (sizeof(T) == sizeof(float)) {
86	            // float32 路径: 直接 Relu
87	            AscendC::Relu(yLocal, xLocal, curTileLength);
88	        } else {
89	            // float16 / bfloat16 路径: 升精度到 float32 计算，再降精度输出
90	            AscendC::LocalTensor<float> xFp32 = castBufX.Get<float>();
91	            AscendC::LocalTensor<float> yFp32 = castBufY.Get<float>();
92	
93	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
94	            AscendC::Relu(yFp32, xFp32, curTileLength);
95	            AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
96	        }
97	
98	        outQueueY.EnQue<T>(yLocal);
99	        inQueueX.FreeTensor(xLocal);
100	    }
101	
102	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
103	    {
104	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
105	        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, curTileLength);
106	        outQueueY.FreeTensor(yLocal);
107	    }
108	
109	private:
110	    AscendC::TPipe pipe;
111	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
112	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
113	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufX;
114	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufY;
115	    AscendC::GlobalTensor<T> xGm;
116	    AscendC::GlobalTensor<T> yGm;
117	    int64_t blockLength;
118	    int64_t tileLength;
119	};
120	
121	extern "C" __global__ __aicore__ void relu(GM_ADDR x, GM_ADDR y,
122	                                            int64_t formerNum, int64_t formerLength,
123	                                            int64_t tailLength, int64_t tileLength,
124	                                            int64_t dtypeSize, int64_t isBfloat16)
125	{
126	    if (dtypeSize == 2) {
127	        if (isBfloat16) {
128	            KernelRelu<bfloat16_t> op;
129	            op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
130	            op.Process();
131	        } else {
132	            KernelRelu<half> op;
133	            op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
134	            op.Process();
135	        }
136	    } else {
137	        KernelRelu<float> op;
138	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
139	        op.Process();
140	    }
141	}
