13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T_X, typename T_G>
16	class KernelHardsigmoidBackward {
17	public:
18	    __aicore__ inline KernelHardsigmoidBackward() {}
19	
20	    __aicore__ inline void Init(GM_ADDR g, GM_ADDR x, GM_ADDR y,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	
26	        if (blockIdx < formerNum) {
27	            this->blockLength = formerLength;
28	            int64_t offset = formerLength * blockIdx;
29	            gGm.SetGlobalBuffer((__gm__ T_G *)g + offset, formerLength);
30	            xGm.SetGlobalBuffer((__gm__ T_X *)x + offset, formerLength);
31	            yGm.SetGlobalBuffer((__gm__ T_X *)y + offset, formerLength);
32	        } else {
33	            this->blockLength = tailLength;
34	            int64_t tailIdx = blockIdx - formerNum;
35	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
36	            gGm.SetGlobalBuffer((__gm__ T_G *)g + offset, tailLength);
37	            xGm.SetGlobalBuffer((__gm__ T_X *)x + offset, tailLength);
38	            yGm.SetGlobalBuffer((__gm__ T_X *)y + offset, tailLength);
39	        }
40	
41	        this->tileLength = tileLength;
42	
43	        pipe.InitBuffer(inQueueG, BUFFER_NUM, tileLength * sizeof(T_G));
44	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T_X));
45	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T_X));
46	
47	        if constexpr (sizeof(T_G) < sizeof(float)) {
48	            pipe.InitBuffer(castBufG, tileLength * sizeof(float));
49	        }
50	        if constexpr (sizeof(T_X) < sizeof(float)) {
51	            pipe.InitBuffer(castBufX, tileLength * sizeof(float));
52	        }
53	
54	        pipe.InitBuffer(h1Buf, tileLength * sizeof(float));
55	        pipe.InitBuffer(negBuf, tileLength * sizeof(float));
56	        pipe.InitBuffer(h2Buf, tileLength * sizeof(float));
57	        pipe.InitBuffer(hBuf, tileLength * sizeof(float));
58	        pipe.InitBuffer(zeroBuf, tileLength * sizeof(float));
59	        pipe.InitBuffer(maskBuf, tileLength * sizeof(float));
60	        pipe.InitBuffer(gradBuf, tileLength * sizeof(float));
61	
62	        if constexpr (sizeof(T_X) < sizeof(float)) {
63	            pipe.InitBuffer(yFp32Buf, tileLength * sizeof(float));
64	        }
65	    }
66	
67	    __aicore__ inline void Process()
68	    {
69	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
70	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
71	
72	        int64_t alignElements = 32 / static_cast<int64_t>(sizeof(T_X));
73	        int64_t alignedTailLen = ((tailTileLength + alignElements - 1) / alignElements) * alignElements;
74	
75	        for (int64_t i = 0; i < tileNum - 1; ++i) {
76	            CopyIn(i, this->tileLength);
77	            Compute(i, this->tileLength);
78	            CopyOut(i, this->tileLength);
79	        }
80	        if (tileNum > 0) {
81	            CopyIn(tileNum - 1, alignedTailLen);
82	            Compute(tileNum - 1, alignedTailLen);
83	            CopyOut(tileNum - 1, tailTileLength);
84	        }
85	    }
86	
87	private:
88	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
89	    {
90	        AscendC::LocalTensor<T_G> gLocal = inQueueG.AllocTensor<T_G>();
91	        AscendC::DataCopyExtParams copyParamsG{1, static_cast<uint32_t>(curTileLength * sizeof(T_G)), 0, 0, 0};
92	        AscendC::DataCopyPadExtParams<T_G> padParamsG{false, 0, 0, 0};
93	        AscendC::DataCopyPad(gLocal, gGm[progress * this->tileLength], copyParamsG, padParamsG);
94	        inQueueG.EnQue(gLocal);
95	
96	        AscendC::LocalTensor<T_X> xLocal = inQueueX.AllocTensor<T_X>();
97	        AscendC::DataCopyExtParams copyParamsX{1, static_cast<uint32_t>(curTileLength * sizeof(T_X)), 0, 0, 0};
98	        AscendC::DataCopyPadExtParams<T_X> padParamsX{false, 0, 0, 0};
99	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParamsX, padParamsX);
100	        inQueueX.EnQue(xLocal);
101	    }
102	
103	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
104	    {
105	        AscendC::LocalTensor<T_G> gLocal = inQueueG.DeQue<T_G>();
106	        AscendC::LocalTensor<T_X> xLocal = inQueueX.DeQue<T_X>();
107	
108	        if constexpr (sizeof(T_X) == sizeof(float) && sizeof(T_G) == sizeof(float)) {
109	            // Both inputs are FP32: direct compute
110	            AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
111	            ComputeFp32Core(yLocal, xLocal, gLocal, curTileLength);
112	            outQueueY.EnQue<float>(yLocal);
113	        } else {
114	            // At least one input is non-FP32: Cast inputs → FP32 compute → Cast output
115	            AscendC::LocalTensor<float> gFp32;
116	            if constexpr (sizeof(T_G) < sizeof(float)) {
117	                gFp32 = castBufG.Get<float>();
118	                AscendC::Cast(gFp32, gLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
119	            } else {
120	                gFp32 = gLocal;
121	            }
122	
123	            AscendC::LocalTensor<float> xFp32;
124	            if constexpr (sizeof(T_X) < sizeof(float)) {
125	                xFp32 = castBufX.Get<float>();
126	                AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
127	            } else {
128	                xFp32 = xLocal;
129	            }
130	
131	            AscendC::LocalTensor<float> yFp32;
132	            if constexpr (sizeof(T_X) < sizeof(float)) {
133	                yFp32 = yFp32Buf.Get<float>();
134	            } else {
135	                yFp32 = outQueueY.AllocTensor<float>();
136	            }
137	            ComputeFp32Core(yFp32, xFp32, gFp32, curTileLength);
138	
139	            if constexpr (sizeof(T_X) < sizeof(float)) {
140	                AscendC::LocalTensor<T_X> yLocal = outQueueY.AllocTensor<T_X>();
141	                AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
142	                outQueueY.EnQue<T_X>(yLocal);
143	            } else {
144	                outQueueY.EnQue<float>(yFp32);
145	            }
146	        }
147	
148	        inQueueG.FreeTensor(gLocal);
149	        inQueueX.FreeTensor(xLocal);
150	    }
151	
152	    __aicore__ inline void ComputeFp32Core(
153	        AscendC::LocalTensor<float> yLocal,
154	        AscendC::LocalTensor<float> xFp32,
155	        AscendC::LocalTensor<float> gFp32,
156	        int64_t len)
157	    {
158	        AscendC::LocalTensor<float> h1Local = h1Buf.Get<float>();
159	        AscendC::LocalTensor<float> negLocal = negBuf.Get<float>();
160	        AscendC::LocalTensor<float> h2Local = h2Buf.Get<float>();
161	        AscendC::LocalTensor<float> hLocal = hBuf.Get<float>();
162	        AscendC::LocalTensor<float> zeroLocal = zeroBuf.Get<float>();
163	        AscendC::LocalTensor<uint8_t> maskLocal = maskBuf.Get<uint8_t>();
164	        AscendC::LocalTensor<float> gradLocal = gradBuf.Get<float>();
165	
166	        // h1 = Relu(x + 3)
167	        AscendC::Adds(h1Local, xFp32, 3.0f, len);
168	        AscendC::Relu(h1Local, h1Local, len);
169	
170	        // h2 = Relu(3 - x)
171	        AscendC::Muls(negLocal, xFp32, -1.0f, len);
172	        AscendC::Adds(h2Local, negLocal, 3.0f, len);
173	        AscendC::Relu(h2Local, h2Local, len);
174	
175	        // h = Min(h1, h2), h > 0 when -3 < x < 3, h == 0 otherwise
176	        AscendC::Min(hLocal, h1Local, h2Local, len);
177	
178	        // Fill zero buffer
179	        AscendC::Duplicate(zeroLocal, 0.0f, len);
180	
181	        // mask = (h > 0)
182	        AscendC::Compare(maskLocal, hLocal, zeroLocal, AscendC::CMPMODE::GT, len);
183	
184	        // grad_scaled = g / 6.0
185	        float oneOverSix = 1.0f / 6.0f;
186	        AscendC::Muls(gradLocal, gFp32, oneOverSix, len);
187	
188	        // result = (h > 0) ? grad_scaled : 0
189	        AscendC::Select(yLocal, maskLocal, gradLocal, zeroLocal,
190	                        AscendC::SELMODE::VSEL_CMPMASK_SPR, len);
191	    }
192	
193	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
194	    {
195	        AscendC::LocalTensor<T_X> yLocal = outQueueY.DeQue<T_X>();
196	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T_X)), 0, 0, 0};
197	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
198	        outQueueY.FreeTensor(yLocal);
199	    }
