202	    AscendC::TPipe pipe;
203	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueG;
204	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
205	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
206	
207	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufG;
208	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufX;
209	    AscendC::TBuf<AscendC::TPosition::VECCALC> h1Buf;
210	    AscendC::TBuf<AscendC::TPosition::VECCALC> negBuf;
211	    AscendC::TBuf<AscendC::TPosition::VECCALC> h2Buf;
