            if constexpr (sizeof(T_X) < sizeof(float)) {
                xFp32 = castBufX.Get<float>();
                AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            } else {
                xFp32 = xLocal;
